const crypto = require('node:crypto')
const { parse, compileTemplate } = require('@vue/compiler-sfc')

const hash = value => crypto.createHash('sha256').update(value).digest('hex').slice(0, 20)
const COMPONENT_ADAPTERS = Object.freeze({
  'v-slider': 'range', 'v-switch': 'switch', 'v-checkbox': 'switch',
  'v-select': 'select', 'v-radio-group': 'select',
  'v-text-field': 'text-input', 'v-textarea': 'text-input',
  'v-progress-linear': 'meter', 'v-progress-circular': 'meter'
})
const XY_SERIES_CONTAINER_TAGS = new Set(['div', 'section', 'article', 'main', 'aside', 'svg', 'g'])
const SIMPLE_IDENTIFIER = /^[A-Za-z_$][A-Za-z0-9_$]*$/
const SIMPLE_PROPERTY_PATH = /^[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)*$/
const UNSAFE_PROPERTY_NAMES = new Set(['__proto__', 'prototype', 'constructor'])

function safePropertyPath (value) {
  return SIMPLE_PROPERTY_PATH.test(value) &&
    value.split('.').every(part => !UNSAFE_PROPERTY_NAMES.has(part))
}

function attribute (node, name) {
  const prop = (node.props || []).find(item => item.type === 6 && item.name === name)
  return prop?.value?.content || ''
}

function hasDirective (node, names) {
  return (node.props || []).some(prop => prop.type === 7 && names.includes(prop.name))
}

function hasBoundAttribute (node, names) {
  return (node.props || []).some(prop => prop.type === 7 && prop.name === 'bind' &&
    names.includes(prop.arg?.content))
}

function hasAttribute (node, names) {
  return (node.props || []).some(prop => prop.type === 6 && names.includes(prop.name)) ||
    hasBoundAttribute(node, names)
}

function hasNestedHandlers (node) {
  return (node.children || []).some(child => hasDirective(child, ['on']) || hasNestedHandlers(child))
}

function enabledBooleanProp (node, names) {
  return (node.props || []).some(prop => {
    if (prop.type === 6) return names.includes(prop.name)
    return prop.type === 7 && prop.name === 'bind' && names.includes(prop.arg?.content) &&
      prop.exp?.content?.trim() !== 'false'
  })
}

function candidateAdapter (node) {
  const tag = node.tag.toLowerCase()
  if (COMPONENT_ADAPTERS[tag]) return COMPONENT_ADAPTERS[tag]
  if (tag === 'input') {
    const type = (attribute(node, 'type') || 'text').toLowerCase()
    if (type === 'range' || type === 'number') return 'range'
    if (type === 'checkbox') return 'switch'
    if (type === 'text') return 'text-input'
    return null
  }
  if (tag === 'textarea') return 'text-input'
  if (tag === 'select') return 'select'
  if (tag === 'button' && (attribute(node, 'aria-pressed') !== '' || attribute(node, 'role') === 'switch' ||
    hasBoundAttribute(node, ['aria-pressed', 'aria-checked']))) return 'switch'
  if (tag === 'meter' || tag === 'progress') return 'meter'
  if (tag === 'canvas' && hasBoundAttribute(node, ['data-points', 'data-series'])) return 'xy-series'
  if (XY_SERIES_CONTAINER_TAGS.has(tag) && hasBoundAttribute(node, ['data-coordinates'])) return 'xy-series'
  if (attribute(node, 'data-display-only').toLowerCase() === 'true') return null
  if (['span', 'strong', 'b', 'output', 'h1', 'h2', 'h3'].includes(tag) &&
    node.children?.length === 1 && node.children[0].type === 2 &&
    node.children[0].content.trim()) return 'text-display'
  if (['span', 'strong', 'b', 'output', 'h1', 'h2', 'h3'].includes(tag) &&
    node.children?.some(child => child.type === 5)) return 'text-display'
  return null
}

function xySeriesModel (node) {
  const tag = node.tag.toLowerCase()
  const names = tag === 'canvas' ? ['data-points', 'data-series'] : ['data-coordinates']
  const bound = (node.props || []).find(prop => prop.type === 7 && prop.name === 'bind' &&
    names.includes(prop.arg?.content))
  if (!bound || bound.modifiers?.length) return { model: '', valid: false, attribute: names[0] }
  const model = bound.exp?.content?.trim() || ''
  return { model, valid: SIMPLE_IDENTIFIER.test(model), attribute: bound.arg.content,
    presentation: tag === 'canvas' ? 'points' : 'coordinates' }
}

function staticNumericProp (node, name) {
  const bound = (node.props || []).find(prop => prop.type === 7 && prop.name === 'bind' &&
    prop.arg?.content === name)
  if (bound) {
    const expression = bound.exp?.content?.trim() || ''
    return /^-?(?:\d+(?:\.\d*)?|\.\d+)$/.test(expression)
      ? { value: Number(expression), dynamic: false }
      : { value: undefined, dynamic: true }
  }
  const value = attribute(node, name)
  if (value === '' || (name === 'step' && value === 'any')) return { value: undefined, dynamic: false }
  const numeric = Number(value)
  return { value: numeric, dynamic: !Number.isFinite(numeric) }
}

function repeatModelInfo (expression, repeat) {
  const model = String(expression || '').trim()
  if (SIMPLE_IDENTIFIER.test(model)) return { valid: true, repeatModel: null }
  if (!repeat?.valid) return { valid: false, repeatModel: null }
  const indexedPrefix = repeat.index ? `${repeat.source}[${repeat.index}].` : ''
  if (indexedPrefix && model.startsWith(indexedPrefix)) {
    const field = model.slice(indexedPrefix.length)
    if (safePropertyPath(field)) {
      return { valid: true, repeatModel: { kind: 'source-index-property', field } }
    }
  }
  if (repeat.kind === 'item') {
    const escaped = repeat.value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const match = model.match(new RegExp('^' + escaped + '\\.' +
      '(' + SIMPLE_PROPERTY_PATH.source.slice(1, -1) + ')$'))
    return match && safePropertyPath(match[1])
      ? { valid: true, repeatModel: { kind: 'item-property', field: match[1] } }
      : { valid: false, repeatModel: null }
  }
  return model === `${repeat.source}[${repeat.index}]`
    ? { valid: true, repeatModel: { kind: 'array-index' } }
    : { valid: false, repeatModel: null }
}

function displayModel (node, repeat) {
  const dynamic = (node.children || []).filter(child => child.type === 5)
  if (!dynamic.length) return { model: '', valid: true }
  const expression = dynamic.length === 1 ? dynamic[0].content?.content?.trim() : ''
  return { model: expression, ...repeatModelInfo(expression, repeat) }
}

function inputModel (node, allowNumber = false, repeat) {
  const directive = (node.props || []).find(prop => prop.type === 7 && prop.name === 'model')
  if (!directive) return { model: '', valid: true }
  const model = directive.exp?.content?.trim() || ''
  const modifiers = (directive.modifiers || []).map(item => typeof item === 'string' ? item : item.content)
  const info = repeatModelInfo(model, repeat)
  return { model, repeatModel: info.repeatModel,
    valid: !directive.arg && modifiers.every(item => allowNumber && item === 'number') && info.valid }
}

function progressModel (node, repeat) {
  const bound = (node.props || []).find(prop => prop.type === 7 && prop.name === 'bind' &&
    ['model-value', 'modelValue'].includes(prop.arg?.content))
  if (!bound) return inputModel(node, false, repeat)
  const model = bound.exp?.content?.trim() || ''
  const info = repeatModelInfo(model, repeat)
  return { model, repeatModel: info.repeatModel,
    valid: !hasDirective(node, ['model']) && !bound.modifiers?.length && info.valid }
}

function nativeMeterModel (node, repeat) {
  const modelDirective = (node.props || []).find(prop => prop.type === 7 && prop.name === 'model')
  if (modelDirective) {
    const model = modelDirective.exp?.content?.trim() || ''
    const info = repeatModelInfo(model, repeat)
    return { model, repeatModel: info.repeatModel,
      valid: !modelDirective.arg && !modelDirective.modifiers?.length && info.valid }
  }
  const bound = (node.props || []).find(prop => prop.type === 7 && prop.name === 'bind' &&
    prop.arg?.content === 'value')
  if (!bound) return { model: '', valid: true }
  const model = bound.exp?.content?.trim() || ''
  const info = repeatModelInfo(model, repeat)
  return { model, repeatModel: info.repeatModel,
    valid: !bound.modifiers?.length && info.valid }
}

function repeatDescriptor (node) {
  const directive = (node.props || []).find(prop => prop.type === 7 && prop.name === 'for')
  if (!directive) return null
  const parsed = directive.forParseResult
  const source = parsed?.source?.content?.trim() || ''
  const value = parsed?.value?.content?.trim() || ''
  const index = parsed?.key?.content?.trim() || ''
  const keyProp = (node.props || []).find(prop => prop.type === 7 && prop.name === 'bind' &&
    prop.arg?.content === 'key' && !prop.modifiers?.length)
  const key = keyProp?.exp?.content?.trim() || ''
  const locator = `repeat:${hash(`${node.tag}:${node.loc.start.offset}:${directive.exp?.content || ''}`)}`
  let kind = ''
  let reason = ''
  if (!SIMPLE_IDENTIFIER.test(source)) reason = 'v-for source must be one top-level array field'
  else if (!SIMPLE_IDENTIFIER.test(value)) reason = 'v-for item alias must be a simple identifier'
  else if (index && !SIMPLE_IDENTIFIER.test(index)) reason = 'v-for index alias must be a simple identifier'
  else if (!key) reason = 'Repeated controls need a stable :key'
  else if (key === `${value}.id`) kind = 'item'
  else if (index && key === index) kind = 'array'
  else reason = index
    ? 'Object lists need :key="item.id" or array lists need :key="index"'
    : 'Item v-for bindings require :key="item.id"'
  return { locator, source, value, ...(index ? { index } : {}), key, kind,
    markerOnControl: node.tag.toLowerCase() === 'template',
    valid: !reason, ...(reason ? { reason } : {}) }
}

function normalizeMeterVModels (format) {
  const parsed = parse(format, { filename: 'ControlPanel.vue' })
  if (parsed.errors.length || !parsed.descriptor.template?.ast) return format
  const replacements = []
  function visit (node) {
    if (node.type === 1 && ['meter', 'progress'].includes(node.tag.toLowerCase())) {
      const model = (node.props || []).find(prop => prop.type === 7 && prop.name === 'model')
      if (model) {
        const expression = model.exp?.content?.trim() || ''
        if (model.arg || model.modifiers?.length || !/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(expression)) {
          throw new Error('Native meter/progress v-model must be a simple top-level field without modifiers')
        }
        if ((node.props || []).some(prop => prop.type === 7 && prop.name === 'bind' &&
          prop.arg?.content === 'value')) {
          throw new Error('Native meter/progress v-model cannot be combined with :value')
        }
        replacements.push({ start: model.loc.start.offset, end: model.loc.end.offset,
          value: `:value="${expression}"` })
      }
    }
    for (const child of node.children || []) visit(child)
  }
  visit(parsed.descriptor.template.ast)
  let normalized = format
  for (const replacement of replacements.reverse()) {
    normalized = normalized.slice(0, replacement.start) + replacement.value + normalized.slice(replacement.end)
  }
  return normalized
}

function pressedModel (node, repeat) {
  const directive = (node.props || []).find(prop => prop.type === 7 && prop.name === 'bind' &&
    ['aria-pressed', 'aria-checked'].includes(prop.arg?.content))
  if (!directive) return { model: '', valid: true }
  const model = directive.exp?.content?.trim() || ''
  const info = repeatModelInfo(model, repeat)
  return { model, valid: !directive.modifiers?.length &&
    info.valid, repeatModel: info.repeatModel }
}

function openingTagEnd (source, start) {
  let quote = ''
  for (let index = start; index < source.length; index++) {
    const char = source[index]
    if (quote) {
      if (char === quote) quote = ''
    } else if (char === '"' || char === "'") quote = char
    else if (char === '>') return index
  }
  throw new Error('Unclosed element in ControlPanel template')
}

const inspections = new Map()
const MAX_INSPECTIONS = 64
const MAX_INSPECTION_BYTES = 4 * 1024 * 1024
let inspectionBytes = 0

function inspectTemplate (format) {
  if (typeof format !== 'string' || format.length > 1024 * 1024) {
    throw new Error('ControlPanel template must be text under 1 MB')
  }
  const cached = inspections.get(format)
  if (cached) {
    inspections.delete(format)
    inspections.set(format, cached)
    return structuredClone(cached.value)
  }
  const value = compileInspection(format)
  const bytes = 2 * (format.length + JSON.stringify(value).length)
  if (bytes <= MAX_INSPECTION_BYTES) {
    while (inspections.size && (inspections.size >= MAX_INSPECTIONS || inspectionBytes + bytes > MAX_INSPECTION_BYTES)) {
      const oldest = inspections.keys().next().value
      inspectionBytes -= inspections.get(oldest).bytes
      inspections.delete(oldest)
    }
    inspections.set(format, { value: structuredClone(value), bytes })
    inspectionBytes += bytes
  }
  return value
}

function compileInspection (format) {
  const { descriptor, errors } = parse(format, { filename: 'ControlPanel.vue' })
  if (errors.length) throw new Error('Invalid ControlPanel template: ' + errors[0].message)
  // Parsing alone accepts directives that Vue cannot render (for example meter v-model).
  if (descriptor.template) {
    const normalized = normalizeMeterVModels(format)
    const normalizedDescriptor = parse(normalized, { filename: 'ControlPanel.vue' }).descriptor
    const compiled = compileTemplate({ source: normalizedDescriptor.template.content,
      filename: 'ControlPanel.vue', id: 'control-panel' })
    if (compiled.errors.length) {
      const error = compiled.errors[0]
      const line = error.loc?.start?.line
      const location = line ? ` at line ${line + descriptor.template.loc.start.line - 1}` : ''
      throw new Error(`Invalid ControlPanel template${location}: ${error.message || error}`)
    }
  }
  const candidates = []
  const counts = new Map()
  const repeatMarkers = []

  function visit (node, repeatContext = null) {
    if (node.type === 1) {
      if (node.tag.toLowerCase().startsWith('v-') && node.isSelfClosing) {
        throw new Error(`Vuetify component <${node.tag}> needs an explicit closing tag in Dashboard templates`)
      }
      const ownRepeat = repeatDescriptor(node)
      const activeRepeat = ownRepeat
        ? repeatContext ? { ...ownRepeat, valid: false, reason: 'Nested v-for bindings are not supported' } : ownRepeat
        : repeatContext
      const insideRepeat = Boolean(activeRepeat)
      if (ownRepeat?.valid && !repeatContext && !ownRepeat.markerOnControl) {
        repeatMarkers.push({ offset: openingTagEnd(format, node.loc.start.offset),
          locator: ownRepeat.locator, key: ownRepeat.key })
      }
      const adapter = candidateAdapter(node)
      const customAttribute = (node.props || []).some(prop =>
        (prop.type === 6 && prop.name.startsWith('data-cp-')) ||
        (prop.type === 7 && prop.name === 'bind' && prop.arg?.content?.startsWith('data-cp-')))
      if (customAttribute) throw new Error('ControlPanel-specific data-cp-* attributes are no longer supported')
      if (adapter) {
        const component = COMPONENT_ADAPTERS[node.tag.toLowerCase()] ? node.tag.toLowerCase() : ''
        const display = adapter === 'text-display'
          ? displayModel(node, activeRepeat)
          : adapter === 'xy-series' ? xySeriesModel(node)
          : ['v-progress-linear', 'v-progress-circular'].includes(component) ? progressModel(node, activeRepeat)
          : adapter === 'meter' && !component ? nativeMeterModel(node, activeRepeat)
          : adapter === 'switch' && node.tag.toLowerCase() === 'button'
            ? pressedModel(node, activeRepeat)
            : inputModel(node, adapter === 'range' || adapter === 'select', activeRepeat)
        const source = format.slice(node.loc.start.offset, openingTagEnd(format, node.loc.start.offset) + 1)
        const stableName = attribute(node, 'id') || attribute(node, 'name')
        const locator = stableName
          ? `name:${hash(node.tag + ':' + stableName)}`
          : `tag:${hash(source.replace(/\s+/g, ' ').trim() +
            (adapter === 'text-display' ? ':' + (display.model || node.children[0]?.content?.trim() || '') : ''))}`
        const explicitLogic = hasDirective(node, ['on']) ||
          (node.props || []).some(prop => prop.type === 7 && prop.name === 'bind' &&
            ['value', 'checked', 'model-value', 'modelValue'].includes(prop.arg?.content) &&
            !(adapter === 'meter' && !component && prop.arg?.content === 'value') &&
            !(['v-progress-linear', 'v-progress-circular'].includes(component) &&
              ['model-value', 'modelValue'].includes(prop.arg?.content)))
        const nestedLogic = component === 'v-radio-group' && hasNestedHandlers(node)
        const unboundedNumber = node.tag.toLowerCase() === 'input' &&
          attribute(node, 'type').toLowerCase() === 'number'
        const min = staticNumericProp(node, 'min')
        const max = staticNumericProp(node, 'max')
        const step = staticNumericProp(node, 'step')
        const dynamicBounds = (adapter === 'range' && (min.dynamic || max.dynamic || step.dynamic)) ||
          (adapter === 'meter' && (min.dynamic || max.dynamic))
        const invalidSliderBounds = component === 'v-slider' &&
          ((min.value ?? 0) >= (max.value ?? 100) ||
            (step.value !== undefined && step.value <= 0) || attribute(node, 'step') === 'any')
        const customSwitchValues = component && adapter === 'switch' &&
          ((node.props || []).some(prop => prop.type === 6 &&
            ['multiple', 'value', 'true-value', 'false-value'].includes(prop.name)) ||
            hasBoundAttribute(node, ['multiple', 'value', 'true-value', 'false-value']))
        const unsupportedSelect = component === 'v-select' &&
          enabledBooleanProp(node, ['multiple', 'return-object', 'clearable'])
        const unsupportedRadio = component === 'v-radio-group' &&
          (hasAttribute(node, ['multiple', 'type']) || nestedLogic)
        const unsupportedTextType = component === 'v-text-field' &&
          ((attribute(node, 'type') && attribute(node, 'type') !== 'text') ||
            hasBoundAttribute(node, ['type']))
        const unsupportedProgress = component === 'v-progress-linear' &&
          (enabledBooleanProp(node, ['indeterminate', 'clickable']) ||
            hasAttribute(node, ['min', 'step']) ||
            (max.value !== undefined && max.value <= 0))
        const unsupportedCircular = component === 'v-progress-circular' &&
          (enabledBooleanProp(node, ['indeterminate']) || hasAttribute(node, ['min', 'max', 'step']))
        const candidate = {
          locator, adapter,
          ...(adapter === 'switch' && node.tag.toLowerCase() === 'button' ? { button: true } : {}),
          ...(component ? { component } : {}),
          ...(activeRepeat ? { repeat: activeRepeat } : {}),
          label: attribute(node, 'aria-label') || attribute(node, 'label') || attribute(node, 'title') ||
            stableName || display.model || (adapter === 'text-display' ? node.children[0]?.content?.trim() : '') || node.tag,
          ...(display.model ? { model: display.model } : {}),
          ...(adapter === 'range' || adapter === 'meter' ? {
            min: ['v-progress-linear', 'v-progress-circular'].includes(component) ? 0
              : min.value !== undefined ? min.value : unboundedNumber ? undefined : 0,
            max: component === 'v-progress-circular' ? 100
              : max.value !== undefined ? max.value : unboundedNumber ? undefined
              : adapter === 'meter' && !component ? 1 : 100,
            step: ['v-progress-linear', 'v-progress-circular'].includes(component) ? 'any'
              : step.value !== undefined ? String(step.value) : attribute(node, 'step') ||
                (adapter === 'meter' ? 'any' : '1')
          } : {}),
          ...(attribute(node, 'data-unit') ? { unit: attribute(node, 'data-unit') } : {}),
          line: node.loc.start.line,
          supported: (!insideRepeat || Boolean(activeRepeat.valid && display.valid)) && !explicitLogic && display.valid && !dynamicBounds &&
            !invalidSliderBounds &&
            !customSwitchValues && !unsupportedSelect && !unsupportedRadio &&
            !unsupportedTextType && !unsupportedProgress && !unsupportedCircular &&
            (!component || Boolean(display.model)),
          reason: insideRepeat && !activeRepeat.valid ? activeRepeat.reason :
            explicitLogic ? 'Controls with existing handlers or reactive value bindings need a dedicated adapter' :
              !display.valid ? (adapter === 'text-display' ? 'Dynamic text needs one writable data field' :
                'Only a simple Vue v-model field is supported') :
                dynamicBounds ? 'Dynamic numeric bounds need a dedicated adapter' :
                  invalidSliderBounds ? 'Slider min, max, and step must form a valid range' :
                  customSwitchValues ? 'Custom switch values need a dedicated adapter' :
                    unsupportedSelect ? 'Only a single scalar Vuetify selection is supported' :
                      unsupportedRadio ? 'Radio groups need scalar values without separate handlers' :
                      unsupportedTextType ? 'Only text Vuetify fields are supported' :
                        unsupportedProgress ? 'Progress needs a determinate positive range' :
                          unsupportedCircular ? 'Circular progress uses a determinate 0-100 range' :
              adapter === 'xy-series' && !display.model
                ? display.attribute === 'data-coordinates'
                  ? 'Map coordinate containers need :data-coordinates="coordinates"'
                  : 'Canvas needs :data-points="series" or :data-series="series"'
                : component && !display.model ? 'Vuetify controls need a simple Vue v-model field' : ''
        }
        candidates.push({ ...candidate, offset: openingTagEnd(format, node.loc.start.offset) })
        counts.set(locator, (counts.get(locator) || 0) + 1)
      }
      for (const child of node.children || []) visit(child, activeRepeat)
      return
    }
    for (const child of node.children || []) visit(child, repeatContext)
    for (const branch of node.branches || []) visit(branch, repeatContext)
  }

  if (descriptor.template?.ast) visit(descriptor.template.ast)
  for (const candidate of candidates) {
    if (counts.get(candidate.locator) > 1) {
      candidate.supported = false
      candidate.reason = 'This element is ambiguous; give it a unique HTML id or name'
    }
  }
  return { candidates, repeatMarkers, templateHash: hash(format) }
}

function instrumentTemplate (format) {
  const inspected = inspectTemplate(format)
  let rendered = format
  const insertions = new Map()
  const addInsertion = (offset, value) => {
    const list = insertions.get(offset) || []
    list.push(value)
    insertions.set(offset, list)
  }
  for (const candidate of inspected.candidates) {
    addInsertion(candidate.offset, `data-cp-auto="${candidate.locator}"`)
    if (candidate.repeat?.markerOnControl) {
      addInsertion(candidate.offset,
        `data-cp-repeat="${candidate.repeat.locator}" :data-cp-repeat-key="String(${candidate.repeat.key})"`)
    }
  }
  for (const marker of inspected.repeatMarkers) {
    addInsertion(marker.offset, `data-cp-repeat="${marker.locator}" :data-cp-repeat-key="String(${marker.key})"`)
  }
  for (const [offset, attributes] of [...insertions.entries()].sort((a, b) => b[0] - a[0])) {
    const before = rendered.slice(0, offset)
    const selfClosing = /\/\s*$/.test(before)
    const insertAt = selfClosing ? before.lastIndexOf('/') : offset
    rendered = rendered.slice(0, insertAt) + ' ' + attributes.join(' ') + rendered.slice(insertAt)
  }
  return {
    format: normalizeMeterVModels(rendered),
    candidates: inspected.candidates.map(({ offset, ...candidate }) => candidate),
    templateHash: inspected.templateHash
  }
}

module.exports = { inspectTemplate, instrumentTemplate, normalizeMeterVModels }
